class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        int k = 0;
        for (int x : nums) {
            if (k < 2 || x > nums[k - 2]) {
                nums[k++] = x;
            }
        }
        return k;
    }
};

class Solution {
    public int removeDuplicates(int[] nums) {
        int k = 0;
        for (int x : nums) {
            if (k < 2 || x > nums[k - 2]) {
                nums[k++] = x;
            }
        }
        return k;
    }
}

var removeDuplicates = function(nums) {
    let k = 0;
    for (const x of nums) {
        if (k < 2 || x > nums[k - 2]) {
            nums[k++] = x;
        }
    }
    return k;
};
